add_filter( 'woocommerce_checkout_fields', 'perfectpixel_toggle_checkbox_fields', 9999 );
add_action( 'woocommerce_after_checkout_form', 'perfectpixel_toggle_checkbox_script' );
add_action( 'woocommerce_checkout_create_order', 'perfectpixel_toggle_checkbox_save', 10, 2 );
add_action( 'woocommerce_admin_order_data_after_billing_address', 'perfectpixel_toggle_checkbox_admin' );

function perfectpixel_toggle_checkbox_fields( $fields ) {
	$fields['order']['perfectpixel_toggle'] = array(
		'type'     => 'checkbox',
		'label'    => '{{toggle_label}}',
		'class'    => array( 'form-row-wide' ),
		'priority' => 5,
	);
	$fields['order']['perfectpixel_extra'] = array(
		'type'     => 'textarea',
		'label'    => '{{extra_label}}',
		'class'    => array( 'form-row-wide' ),
		'priority' => 6,
	);
	return $fields;
}

function perfectpixel_toggle_checkbox_script() {
	?>
	<script>
	( function () {
		var box = document.getElementById( 'perfectpixel_toggle' );
		var row = document.getElementById( 'perfectpixel_extra_field' );
		if ( ! box || ! row ) {
			return;
		}
		var update = function () {
			row.style.display = box.checked ? '' : 'none';
		};
		box.addEventListener( 'change', update );
		update();
	} )();
	</script>
	<?php
}

function perfectpixel_toggle_checkbox_save( $order, $data ) {
	if ( ! empty( $_POST['perfectpixel_toggle'] ) && ! empty( $_POST['perfectpixel_extra'] ) ) { // phpcs:ignore WordPress.Security.NonceVerification
		$order->update_meta_data( '_perfectpixel_extra', sanitize_textarea_field( wp_unslash( $_POST['perfectpixel_extra'] ) ) ); // phpcs:ignore WordPress.Security.NonceVerification
	}
}

function perfectpixel_toggle_checkbox_admin( $order ) {
	$value = $order->get_meta( '_perfectpixel_extra' );
	if ( '' !== (string) $value ) {
		printf( '<p><strong>%s:</strong><br>%s</p>', esc_html( '{{extra_label}}' ), nl2br( esc_html( $value ) ) );
	}
}
